SELECT s.result_id AS GS_Result_ID, s.run_id AS GS_Run_ID, CAST(s.rule_id AS INTEGER) AS GS_Rule_ID, s.rule_group AS GS_Rule_Group, s.rule_variant AS GS_Rule_Variant, s.project_name AS GS_Project_Name, s.process_name AS GS_Process_Name, s.run_key AS GS_Run_Key, s.seq_no AS GS_Seq_No, s.start_time AS GS_Start_Dtts, s.end_time AS GS_End_Dtts, CAST(s.start_time AS DATE) AS GS_Run_Dt, s.total_records AS GS_Total_Records, s.failed_records AS GS_Failed_Records, s.distinct_failed_records AS GS_Distinct_Failed_Records, s.duplicate_records AS GS_Duplicate_Records, s.failure_pct AS GS_Failure_Pct, s.threshold_pct_used AS GS_Threshold_Pct_Used, s.threshold_count_used AS GS_Threshold_Count_Used, s.threshold_operator_used AS GS_Threshold_Operator_Used, s.severity AS GS_Severity, s.status AS GS_Status, s.error_message AS GS_Error_Message, CASE WHEN s.status = 'FAIL' THEN 1 ELSE 0 END AS GS_Fail_Ind, CAST(1 AS INTEGER) AS GS_Result_Cnt
FROM HSABC_V.gre_results s
WHERE s.active_ind = 'Y' AND UPPER(TRIM(s.rule_group)) LIKE 'ODAG1%'
